-- ═══════════════════════════════════════════════════════════════════
-- Sirnaaz by Mehar — Supabase setup
-- Supabase dashboard → SQL Editor → New query → paste this whole file → Run.
--
-- SAFE TO RUN MORE THAN ONCE. Every table, index and setting is created only if it is missing,
-- and nothing that already exists is deleted or overwritten (your products, orders and settings are kept).
-- It runs as ONE transaction: if anything fails, nothing at all is changed.
-- The last result table shows a check list — every row should say OK.
-- Generated by `npm run db:build-sql` — do not edit by hand.
-- ═══════════════════════════════════════════════════════════════════
BEGIN;

CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());

-- ───────── migration 001_init.sql ─────────
-- Sirnaaz by Mehar — initial schema (safe to run more than once: every object is created only if missing)
-- Money is stored as whole rupees (INTEGER). Convert to paise only at the payment-gateway boundary.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ───────── Catalogue ─────────
CREATE TABLE IF NOT EXISTS categories (
  id          SERIAL PRIMARY KEY,
  slug        TEXT NOT NULL UNIQUE,
  name        TEXT NOT NULL,
  tagline     TEXT NOT NULL DEFAULT '',
  sort_order  INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS products (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name            TEXT NOT NULL,
  slug            TEXT NOT NULL UNIQUE,
  description     TEXT NOT NULL DEFAULT '',
  details         TEXT[] NOT NULL DEFAULT '{}',
  price           INTEGER NOT NULL CHECK (price > 0),
  sale_price      INTEGER CHECK (sale_price IS NULL OR (sale_price > 0 AND sale_price < price)),
  category_id     INTEGER NOT NULL REFERENCES categories(id),
  colour          TEXT NOT NULL DEFAULT '',
  fabric          TEXT NOT NULL DEFAULT '',
  care            TEXT[] NOT NULL DEFAULT '{}',
  fit             TEXT NOT NULL DEFAULT '',
  delivery_info   TEXT NOT NULL DEFAULT '',
  return_info     TEXT NOT NULL DEFAULT '',
  is_featured     BOOLEAN NOT NULL DEFAULT FALSE,
  is_new_arrival  BOOLEAN NOT NULL DEFAULT FALSE,
  is_active       BOOLEAN NOT NULL DEFAULT TRUE,   -- inactive = hidden from customers
  is_sold_out     BOOLEAN NOT NULL DEFAULT FALSE,  -- manual override
  popularity      INTEGER NOT NULL DEFAULT 0,
  artwork         JSONB,                           -- placeholder illustration recipe, used until photos exist
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category_id);

CREATE TABLE IF NOT EXISTS product_variants (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id  UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  size        TEXT NOT NULL CHECK (size IN ('S','M','L','XL','XXL','XXXL')),
  sku         TEXT UNIQUE,
  UNIQUE (product_id, size)
);

-- One row per variant (= per size). Stock can never go below zero.
CREATE TABLE IF NOT EXISTS inventory (
  variant_id  UUID PRIMARY KEY REFERENCES product_variants(id) ON DELETE CASCADE,
  quantity    INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS product_images (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id   UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  url          TEXT NOT NULL,
  storage_key  TEXT NOT NULL,
  position     INTEGER NOT NULL DEFAULT 0,
  is_primary   BOOLEAN NOT NULL DEFAULT FALSE,
  alt          TEXT NOT NULL DEFAULT '',
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS product_images_product_idx ON product_images(product_id, position);
CREATE UNIQUE INDEX IF NOT EXISTS product_images_one_primary ON product_images(product_id) WHERE is_primary;

-- ───────── People ─────────
CREATE TABLE IF NOT EXISTS users (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email          TEXT NOT NULL UNIQUE,     -- stored lower-case
  name           TEXT NOT NULL,
  phone          TEXT NOT NULL DEFAULT '',
  password_hash  TEXT NOT NULL,            -- argon2id, never plain text
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS admin_users (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email          TEXT NOT NULL UNIQUE,
  name           TEXT NOT NULL,
  password_hash  TEXT NOT NULL,
  is_active      BOOLEAN NOT NULL DEFAULT TRUE,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_login_at  TIMESTAMPTZ
);

-- Sessions store only a SHA-256 hash of the cookie token.
CREATE TABLE IF NOT EXISTS sessions (
  token_hash  TEXT PRIMARY KEY,
  user_id     UUID REFERENCES users(id) ON DELETE CASCADE,
  admin_id    UUID REFERENCES admin_users(id) ON DELETE CASCADE,
  expires_at  TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK ((user_id IS NULL) <> (admin_id IS NULL))
);

CREATE TABLE IF NOT EXISTS password_resets (
  token_hash  TEXT PRIMARY KEY,
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at  TIMESTAMPTZ NOT NULL,
  used_at     TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS addresses (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  full_name   TEXT NOT NULL,
  mobile      TEXT NOT NULL,
  house       TEXT NOT NULL,
  address     TEXT NOT NULL,
  area        TEXT NOT NULL DEFAULT '',
  city        TEXT NOT NULL,
  state       TEXT NOT NULL,
  pincode     TEXT NOT NULL,
  country     TEXT NOT NULL DEFAULT 'India',
  is_default  BOOLEAN NOT NULL DEFAULT FALSE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS wishlist (
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  product_id  UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, product_id)
);

-- ───────── Commerce ─────────
CREATE TABLE IF NOT EXISTS coupons (
  code          TEXT PRIMARY KEY,           -- upper-case
  description   TEXT NOT NULL DEFAULT '',
  type          TEXT NOT NULL CHECK (type IN ('percent','flat')),
  value         INTEGER NOT NULL CHECK (value > 0),
  min_subtotal  INTEGER NOT NULL DEFAULT 0,
  is_active     BOOLEAN NOT NULL DEFAULT TRUE,
  expires_at    TIMESTAMPTZ
);

CREATE SEQUENCE IF NOT EXISTS order_number_seq START 1001;

CREATE TABLE IF NOT EXISTS orders (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  number           TEXT NOT NULL UNIQUE,
  user_id          UUID REFERENCES users(id) ON DELETE SET NULL,  -- null = guest checkout
  view_token_hash  TEXT NOT NULL,                                 -- lets a guest view their own confirmation
  customer_name    TEXT NOT NULL,
  customer_phone   TEXT NOT NULL,
  customer_email   TEXT NOT NULL,
  house            TEXT NOT NULL,
  address          TEXT NOT NULL,
  area             TEXT NOT NULL DEFAULT '',
  city             TEXT NOT NULL,
  state            TEXT NOT NULL,
  pincode          TEXT NOT NULL,
  country          TEXT NOT NULL DEFAULT 'India',
  subtotal         INTEGER NOT NULL,
  shipping         INTEGER NOT NULL,
  discount         INTEGER NOT NULL DEFAULT 0,
  total            INTEGER NOT NULL,
  coupon_code      TEXT,
  payment_method   TEXT NOT NULL CHECK (payment_method IN ('online','cod')),
  payment_status   TEXT NOT NULL CHECK (payment_status IN ('pending','paid','cod-pending','refunded','failed')),
  status           TEXT NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending','confirmed','packed','shipped','delivered','cancelled','refunded')),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS orders_user_idx ON orders(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS orders_created_idx ON orders(created_at DESC);

-- Snapshot of each line at the moment of purchase. Never re-derived from current product data.
CREATE TABLE IF NOT EXISTS order_items (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id      UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  product_id    UUID REFERENCES products(id) ON DELETE SET NULL,
  variant_id    UUID REFERENCES product_variants(id) ON DELETE SET NULL,
  product_name  TEXT NOT NULL,
  product_slug  TEXT NOT NULL,
  image_url     TEXT,
  size          TEXT NOT NULL,
  quantity      INTEGER NOT NULL CHECK (quantity > 0),
  unit_price    INTEGER NOT NULL,
  line_total    INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS order_items_order_idx ON order_items(order_id);

CREATE TABLE IF NOT EXISTS order_status_history (
  id          SERIAL PRIMARY KEY,
  order_id    UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  status      TEXT NOT NULL,
  changed_by  UUID REFERENCES admin_users(id) ON DELETE SET NULL,
  changed_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Single-row settings document, edited from Admin → Settings.
CREATE TABLE IF NOT EXISTS site_settings (
  id          INTEGER PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  data        JSONB NOT NULL,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
INSERT INTO schema_migrations (name) VALUES ('001_init.sql') ON CONFLICT (name) DO NOTHING;

-- ───────── migration 002_serverless_security.sql ─────────
-- 002 — serverless + Supabase hardening
-- • rate limits shared by every function instance
-- • idempotent order creation (double-click / lost response safe)
-- • product photo thumbnails
-- • Row Level Security on every table, and no table access for Supabase's public API roles

-- ───────── Rate limiting (one tiny row per key; single-statement upsert) ─────────
CREATE TABLE IF NOT EXISTS rate_limits (
  key           TEXT PRIMARY KEY,
  window_start  TIMESTAMPTZ NOT NULL DEFAULT now(),
  count         INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS rate_limits_window_idx ON rate_limits(window_start);

-- ───────── Orders: idempotency key (SHA-256 of the browser's checkout key) ─────────
ALTER TABLE orders ADD COLUMN IF NOT EXISTS idempotency_key TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS orders_idempotency_key_idx ON orders(idempotency_key) WHERE idempotency_key IS NOT NULL;

-- ───────── Product images: small version for product cards ─────────
ALTER TABLE product_images ADD COLUMN IF NOT EXISTS thumb_url TEXT;
ALTER TABLE product_images ADD COLUMN IF NOT EXISTS thumb_key TEXT;

-- ───────── Housekeeping indexes ─────────
CREATE INDEX IF NOT EXISTS sessions_expires_idx ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS password_resets_expires_idx ON password_resets(expires_at);

-- ───────── Row Level Security ─────────
-- The website's server connects as the database owner and is the only thing that reads or writes data.
-- Supabase also publishes every table through its own REST/GraphQL API for the `anon` and `authenticated`
-- roles. Enabling RLS with NO policies means those roles can see and change nothing, and the explicit
-- REVOKEs below remove their table privileges as a second lock.
DO $$
DECLARE t TEXT;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
END $$;
-- (The table owner — the server's own login — is not subject to RLS, so the website keeps working.
--  Any table added by a future migration must also run ENABLE ROW LEVEL SECURITY; `npm run db:check` verifies this.)

DO $$
DECLARE r TEXT;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM %I', r);
    END IF;
  END LOOP;
END $$;
INSERT INTO schema_migrations (name) VALUES ('002_serverless_security.sql') ON CONFLICT (name) DO NOTHING;

-- ───────── store data: categories, coupons, settings ─────────
INSERT INTO categories (slug, name, tagline, sort_order) VALUES ('pakistani-suits', 'Pakistani Suits', 'Traditional silhouettes with contemporary elegance.', 0) ON CONFLICT (slug) DO NOTHING;
INSERT INTO categories (slug, name, tagline, sort_order) VALUES ('coord-sets', 'Co-ord Sets', 'Effortless coordinated looks for every occasion.', 1) ON CONFLICT (slug) DO NOTHING;
INSERT INTO categories (slug, name, tagline, sort_order) VALUES ('festive-edit', 'Festive Edit', 'Statement pieces for celebrations and special occasions.', 2) ON CONFLICT (slug) DO NOTHING;
INSERT INTO coupons (code, description, type, value, min_subtotal) VALUES ('WELCOME10', '10% off your first order', 'percent', 10, 0) ON CONFLICT (code) DO NOTHING;
INSERT INTO coupons (code, description, type, value, min_subtotal) VALUES ('SIRNAAZ300', '₹300 off orders above ₹3,999', 'flat', 300, 3999) ON CONFLICT (code) DO NOTHING;
INSERT INTO site_settings (id, data) VALUES (1, '{"brandName":"Sirnaaz by Mehar","tagline":"Timeless Pakistani fashion, curated with love.","instagramHandle":"SirnaazByMehar","facebookUrl":"","youtubeUrl":"","whatsappNumber":"","whatsappMessage":"Hi Sirnaaz by Mehar, I would like to know more about your products.","contactEmail":"sirnaazbymehar@gmail.com","businessPhone":"","city":"New Delhi","stores":[{"name":"Model Town","city":"Delhi","address":""},{"name":"Jammu","city":"Jammu","address":""}],"currency":"INR","shippingCharge":99,"freeShippingThreshold":2499,"deliveryEstimate":"4–7 working days","codEnabled":true,"codMaxOrder":10000,"onlinePaymentsEnabled":false,"shippingPolicy":"We ship across India. Orders are dispatched within 1–2 working days and usually arrive in 4–7 working days. You will receive tracking details by email once your order ships.","returnPolicy":"If there is a problem with your order, email us at sirnaazbymehar@gmail.com with your order number and we will help you."}'::jsonb) ON CONFLICT (id) DO NOTHING;

-- ───────── product photo bucket ─────────
-- Public READ (shoppers must see photos). No upload/delete policies are created, so the only way to add or
-- remove a file is a short-lived signed upload link issued by the website's server to a signed-in admin, or the
-- server itself using the service-role key. Only JPEG/PNG/WebP up to 10 MB are accepted (no SVG/HTML).
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('product-images', 'product-images', TRUE, 10485760, ARRAY['image/webp', 'image/jpeg', 'image/png']::text[])
ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public, file_size_limit = EXCLUDED.file_size_limit, allowed_mime_types = EXCLUDED.allowed_mime_types;

COMMIT;

-- ───────── check list: every row should say OK ─────────
WITH expected(t) AS (VALUES ('addresses'), ('admin_users'), ('categories'), ('coupons'), ('inventory'), ('order_items'), ('order_status_history'), ('orders'), ('password_resets'), ('product_images'), ('product_variants'), ('products'), ('rate_limits'), ('schema_migrations'), ('sessions'), ('site_settings'), ('users'), ('wishlist')),
cols(t, c) AS (VALUES ('orders', 'idempotency_key'), ('product_images', 'thumb_url'), ('product_images', 'thumb_key'))
SELECT * FROM (
  SELECT 1 AS n, 'All ' || (SELECT count(*) FROM expected) || ' tables exist' AS "check",
         CASE WHEN NOT EXISTS (SELECT 1 FROM expected e WHERE to_regclass('public.' || e.t) IS NULL) THEN 'OK'
              ELSE 'PROBLEM: missing ' || (SELECT string_agg(e.t, ', ') FROM expected e WHERE to_regclass('public.' || e.t) IS NULL) END AS status
  UNION ALL SELECT 2, 'Latest columns present',
         CASE WHEN NOT EXISTS (SELECT 1 FROM cols WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema = 'public' AND ic.table_name = cols.t AND ic.column_name = cols.c)) THEN 'OK' ELSE 'PROBLEM' END
  UNION ALL SELECT 3, 'Row Level Security on every table',
         CASE WHEN NOT EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND NOT rowsecurity) THEN 'OK'
              ELSE 'PROBLEM: ' || (SELECT string_agg(tablename, ', ') FROM pg_tables WHERE schemaname = 'public' AND NOT rowsecurity) END
  UNION ALL SELECT 4, 'Public API roles have no table access',
         CASE WHEN NOT EXISTS (SELECT 1 FROM information_schema.role_table_grants WHERE table_schema = 'public' AND grantee IN ('anon', 'authenticated')) THEN 'OK' ELSE 'PROBLEM' END
  UNION ALL SELECT 5, 'Both setup steps recorded',
         CASE WHEN (SELECT count(*) FROM schema_migrations WHERE name IN ('001_init.sql', '002_serverless_security.sql')) = 2 THEN 'OK' ELSE 'PROBLEM' END
  UNION ALL SELECT 6, 'Store settings present', CASE WHEN EXISTS (SELECT 1 FROM site_settings WHERE id = 1) THEN 'OK' ELSE 'PROBLEM' END
  UNION ALL SELECT 7, 'Categories present (' || (SELECT count(*) FROM categories) || ')', CASE WHEN (SELECT count(*) FROM categories) >= 3 THEN 'OK' ELSE 'PROBLEM' END
  UNION ALL SELECT 8, 'Photo bucket product-images is public, 10 MB, JPEG/PNG/WebP only',
         CASE WHEN EXISTS (SELECT 1 FROM storage.buckets WHERE id = 'product-images' AND public AND file_size_limit = 10485760
                           AND allowed_mime_types @> ARRAY['image/webp', 'image/jpeg', 'image/png']::text[] AND ARRAY['image/webp', 'image/jpeg', 'image/png']::text[] @> allowed_mime_types) THEN 'OK' ELSE 'PROBLEM' END
  UNION ALL SELECT 9, 'No upload/delete rules on photo storage (uploads only via the website)',
         CASE WHEN NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND cmd <> 'SELECT') THEN 'OK'
              ELSE 'CHECK: Storage has write rules: ' || (SELECT string_agg(policyname, ', ') FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND cmd <> 'SELECT') END
) checks ORDER BY n;
